from __future__ import annotations

import json
from pathlib import Path
from typing import Any

from flags import (
    clear_runtime_override,
    describe_state,
    format_flags_for_log,
    merge_with_defaults,
    resolve_dashboard_v2_enabled,
    snapshot_flags,
)


def build_ui_config(tenant: str) -> dict[str, Any]:
    enabled = resolve_dashboard_v2_enabled()
    return {
        "tenant": tenant,
        "dashboard_shell": describe_state(enabled),
        "flags": [f.__dict__ for f in snapshot_flags()],
    }


def export_json(config: dict[str, Any]) -> str:
    return json.dumps(config, sort_keys=True)


def write_sample_config(path: Path, tenant: str) -> None:
    path.write_text(export_json(build_ui_config(tenant)), encoding="utf-8")


def summarize_for_support(tenant: str) -> str:
    cfg = build_ui_config(tenant)
    return f"{tenant}:{cfg['dashboard_shell']}"


def default_rollout_matrix() -> dict[str, bool]:
    return {"dashboard_v2": False, "beta": False}


def merged_rollout_view() -> dict[str, bool]:
    return merge_with_defaults(default_rollout_matrix())


def reset_dash_env_for_tests() -> None:
    clear_runtime_override("DASH_V2")


def log_line_for_process() -> str:
    return format_flags_for_log(snapshot_flags())


def attach_process_metadata(payload: dict[str, Any]) -> dict[str, Any]:
    out = dict(payload)
    out["dashboard_v2"] = resolve_dashboard_v2_enabled()
    return out


def compare_with_expected(expected_legacy: bool) -> bool:
    return resolve_dashboard_v2_enabled() != expected_legacy


def noop_stabilizer(values: list[int]) -> int:
    return sum(values) if values else 0


def format_banner(tenant: str) -> str:
    state = describe_state(resolve_dashboard_v2_enabled())
    return f"[{tenant}] {state}"

