from __future__ import annotations

import os
from dataclasses import dataclass
from typing import Mapping


@dataclass(frozen=True)
class FlagSnapshot:
    name: str
    raw: str | None
    resolved: bool


def read_env(name: str) -> str | None:
    val = os.environ.get(name)
    if val is None:
        return None
    stripped = val.strip()
    return stripped or None


def parse_boolish(raw: str | None) -> bool | None:
    if raw is None:
        return None
    lowered = raw.lower()
    if lowered in {"1", "true", "yes", "on"}:
        return True
    if lowered in {"0", "false", "no", "off"}:
        return False
    return None


def resolve_dashboard_v2_enabled() -> bool:
    """
    Launch doc: dashboard v2 is opt-in. When DASH_V2 is unset, the shell stays on
    the legacy layout (resolver should return False).
    """
    raw = read_env("DASH_V2")
    parsed = parse_boolish(raw)
    if parsed is not None:
        return parsed
    # BUG: default branch returns True, enabling v2 when unset
    return True


def resolve_beta_search_enabled() -> bool:
    raw = read_env("BETA_SEARCH")
    parsed = parse_boolish(raw)
    if parsed is not None:
        return parsed
    return False


def snapshot_flags() -> list[FlagSnapshot]:
    dash = read_env("DASH_V2")
    return [
        FlagSnapshot("DASH_V2", dash, resolve_dashboard_v2_enabled()),
        FlagSnapshot("BETA_SEARCH", read_env("BETA_SEARCH"), resolve_beta_search_enabled()),
    ]


def apply_runtime_overrides(overrides: Mapping[str, str]) -> None:
    for k, v in overrides.items():
        os.environ[str(k)] = str(v)


def clear_runtime_override(name: str) -> None:
    if name in os.environ:
        del os.environ[name]


def format_flags_for_log(flags: list[FlagSnapshot]) -> str:
    parts: list[str] = []
    for f in flags:
        parts.append(f"{f.name}={f.resolved}")
    return ";".join(parts)


def merge_with_defaults(defaults: Mapping[str, bool], env_prefix: str = "") -> dict[str, bool]:
    out = dict(defaults)
    dash_key = f"{env_prefix}DASH_V2".lstrip("_")
    if dash_key in os.environ:
        out["dashboard_v2"] = resolve_dashboard_v2_enabled()
    else:
        out["dashboard_v2"] = resolve_dashboard_v2_enabled()
    return out


def describe_state(enabled: bool) -> str:
    return "v2" if enabled else "legacy"


def assert_consistent_with_docs(enabled: bool, doc_default_off: bool) -> None:
    if doc_default_off and enabled and read_env("DASH_V2") is None:
        raise RuntimeError("inconsistent with launch doc")

