import os

import pytest

from flags import clear_runtime_override, resolve_dashboard_v2_enabled


@pytest.fixture(autouse=True)
def _clean_env():
    clear_runtime_override("DASH_V2")
    yield
    clear_runtime_override("DASH_V2")


def test_happy_path_explicit_one_enables():
    os.environ["DASH_V2"] = "1"
    assert resolve_dashboard_v2_enabled() is True


def test_edge_case_explicit_zero_disables():
    os.environ["DASH_V2"] = "0"
    assert resolve_dashboard_v2_enabled() is False


def test_boundary_condition_false_string_disables():
    os.environ["DASH_V2"] = "false"
    assert resolve_dashboard_v2_enabled() is False


def test_unexpected_input_garbage_env_treated_as_unset_for_default():
    os.environ["DASH_V2"] = "maybe"
    assert resolve_dashboard_v2_enabled() is False


def test_integration_unset_env_matches_launch_doc_off():
    os.environ.pop("DASH_V2", None)
    assert resolve_dashboard_v2_enabled() is False
